.insight.gold {{ border-left-color: var(--gold); }}

.insight strong {{ color: #fff; }}

/* Two-column layout */
.col2 {{
  display: grid;
  grid-template-columns: 3fr 2fr;
  gap: 20px;
  margin: 20px 0;
}}

.col2-equal {{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin: 20px 0;
}}

/* Recommendation cards */
.rec-grid {{
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin: 20px 0;
}}

.rec-card {{
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 18px 20px;
}}

.rec-card .rec-num {{
  font-size: 11px;
  color: var(--accent);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
}}

.rec-card h4 {{
  font-size: 15px;
  font-weight: 600;
  color: #fff;
  margin-bottom: 8px;
}}

.rec-card p {{
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.5;
}}

/* Key stat inline */
.stat-inline {{
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  font-weight: 600;
}}

.stat-inline .val {{ font-size: 18px; color: #fff; }}
.stat-inline .label {{ font-size: 12px; color: var(--text-muted); }}

/* Highlight row */
tr.highlight td {{
  background: rgba(240,192,64,0.08);
}}

/* Grid for stat pills */
.stat-pills {{
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 16px 0;
}}

.stat-pill {{
  background: var(--surface2);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 12px;
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
}}

.stat-pill .val {{ color: #fff; font-weight: 600; }}

/* Footer */
.footer {{
  text-align: center;
  color: var(--text-muted);
  font-size: 11px;
  padding: 20px;
  border-top: 1px solid var(--border);
  margin-top: 16px;
}}

/* Responsive */
@media (max-width: 1000px) {{
  .kpi-grid {{ grid-template-columns: repeat(2, 1fr); }}
  .chart-row, .col2, .col2-equal, .rec-grid {{ grid-template-columns: 1fr; }}
}}

@media (max-width: 600px) {{
  .kpi-grid {{ grid-template-columns: 1fr; }}
}}
