    <div class="stat-pill"><span class="label">Std Dev Profit</span> <span class="val">{fmt_usd(summ['std_profit_margin'])}</span></div>
    <div class="stat-pill"><span class="label">% Above Retail</span> <span class="val">{summ['pct_above_retail']}%</span></div>
