        <td>{c['premium_rate']}%</td>
        <td>{c['avg_ratio']}x</td>
        <td>{c['avg_days']}</td>
    </tr>"""

# ── Build model ranking table (top 10 by avg profit) ──
model_sorted = sorted(d['model_stats'], key=lambda x: x['avg_profit'], reverse=True)
model_rows = ""
for i, m in enumerate(model_sorted):
    row_cls = 'top-row' if i < 5 else ''
    cls = 'positive' if m['avg_profit'] > 0 else 'negative'
    model_rows += f"""
    <tr class="{row_cls}">
        <td>{i+1}</td>
        <td>{m['model']}</td>
        <td>{m['transactions']}</td>
        <td>{fmt_usd(m['avg_retail'])}</td>
