        <td class="{cls}">{fmt_usd(m['avg_profit'])}</td>
        <td>{m['premium_rate']}%</td>
        <td>{m['avg_days']}</td>
    </tr>"""

# ── Build colorway ranking rows (top 10) ──
cw_rows = ""
for i, cw in enumerate(d['colorway_stats'][:10]):
    cls = 'positive' if cw['avg_profit'] > 0 else 'negative'
    cw_rows += f"""
