# Helper: format number
def fmt(n, dec=0):
    if dec == 0:
        return f"{n:,.0f}"
    return f"{n:,.{dec}f}"

def fmt_usd(n):
    if n < 0:
        return f"-${abs(n):,.2f}"
    return f"${n:,.2f}"

