<body>

<div class="container">

<!-- ════ HEADER ════ -->
<div class="header">
  <h1>Air Jordan Sneaker Resale Market Analysis</h1>
  <div class="subtitle">Comprehensive secondary-market transaction analysis across models, channels, conditions, and time</div>
  <div class="date-range">{summ['date_range']} · {fmt(summ['total_transactions'])} Transactions · {summ['unique_models']} Models · {summ['unique_colorways']} Colorways · {summ['unique_channels']} Channels</div>
</div>

<!-- ════ KPI DASHBOARD ════ -->
<div class="kpi-grid">
  <div class="kpi-card">
    <div class="kpi-label">Average Profit Margin</div>
    <div class="kpi-value">{fmt_usd(kpis['avg_profit_margin'])}</div>
    <div class="kpi-sub">Median: {fmt_usd(summ['median_profit_margin'])} · Range: {fmt_usd(summ['min_profit'])} to {fmt_usd(summ['max_profit'])}</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Resale Premium Rate</div>
    <div class="kpi-value">{kpis['resale_premium_rate']}%</div>
    <div class="kpi-sub">{fmt(summ['pct_above_retail'],1)}% of transactions sell above retail</div>
  </div>
  <div class="kpi-card">
    <div class="kpi-label">Average Days in Inventory</div>
    <div class="kpi-value">{kpis['avg_days_inventory']} days</div>
