import json

with open('/app/analysis_output.json') as f:
    d = json.load(f)

# Helper: format number
def fmt(n, dec=0):
    if dec == 0:
        return f"{n:,.0f}"
    return f"{n:,.{dec}f}"

def fmt_usd(n):
    if n < 0:
        return f"-${abs(n):,.2f}"
    return f"${n:,.2f}"

summ = d['summary']
kpis = d['kpis']
months_list = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']

# ── Build Channel table rows ──
chan_rows = ""
for c in d['channel_stats']:
    cls = 'positive' if c['avg_profit'] > 0 else 'negative'
    chan_rows += f"""
    <tr>
        <td class="chan-name">{c['channel']}</td>
        <td>{c['transactions']}</td>
        <td>{fmt_usd(c['avg_resale'])}</td>
        <td class="{cls}">{fmt_usd(c['avg_profit'])}</td>
        <td>{c['avg_days']}</td>
        <td>{c['median_days']}</td>
        <td>{c['premium_rate']}%</td>
        <td>{c['avg_ratio']}x</td>
    </tr>"""

# ── Build condition table rows ──
cond_rows = ""
for c in d['condition_stats']:
    cls = 'positive' if c['avg_profit'] > 0 else 'negative'
    cond_rows += f"""
    <tr>
        <td>{c['condition']}</td>
        <td>{c['transactions']}</td>
        <td>{fmt_usd(c['avg_resale'])}</td>
        <td class="{cls}">{fmt_usd(c['avg_profit'])}</td>
        <td>{c['premium_rate']}%</td>
        <td>{c['avg_ratio']}x</td>
        <td>{c['avg_days']}</td>
    </tr>"""

# ── Build model ranking table (top 10 by avg profit) ──
model_sorted = sorted(d['model_stats'], key=lambda x: x['avg_profit'], reverse=True)
model_rows = ""
for i, m in enumerate(model_sorted):
    row_cls = 'top-row' if i < 5 else ''
    cls = 'positive' if m['avg_profit'] > 0 else 'negative'
    model_rows += f"""
    <tr class="{row_cls}">
        <td>{i+1}</td>
        <td>{m['model']}</td>
        <td>{m['transactions']}</td>
        <td>{fmt_usd(m['avg_retail'])}</td>
        <td>{fmt_usd(m['avg_resale'])}</td>
        <td class="{cls}">{fmt_usd(m['avg_profit'])}</td>
        <td>{m['premium_rate']}%</td>
        <td>{m['avg_days']}</td>
    </tr>"""

# ── Build colorway ranking rows (top 10) ──
cw_rows = ""
for i, cw in enumerate(d['colorway_stats'][:10]):
    cls = 'positive' if cw['avg_profit'] > 0 else 'negative'
    cw_rows += f"""
    <tr>
        <td>{i+1}</td>
        <td>{cw['colorway']}</td>
        <td>{cw['transactions']}</td>
        <td>{fmt_usd(cw['avg_resale'])}</td>
        <td class="{cls}">{fmt_usd(cw['avg_profit'])}</td>
        <td>{cw['premium_rate']}%</td>
        <td>{cw['avg_days']}</td>
    </tr>"""

# ── Top combos ──
combo_rows = ""
for i, cb in enumerate(d['combo_data'][:10]):
    cls = 'positive' if cb['avg_profit'] > 0 else 'negative'
    combo_rows += f"""
    <tr>
        <td>{i+1}</td>
        <td>{cb['model']}</td>
        <td>{cb['colorway']}</td>
        <td>{cb['txns']}</td>
        <td>{fmt_usd(cb['avg_resale'])}</td>
        <td class="{cls}">{fmt_usd(cb['avg_profit'])}</td>
        <td>{cb['premium_rate']}%</td>
        <td>{cb['avg_days']}</td>
    </tr>"""

# ── Condition model cross ──
cond_model_rows = ""
for cm in d['condition_model']:
    ds_val = cm.get('Deadstock (Brand New)', 0) or 0
    vnds_val = cm.get('VNDS (Very Near Deadstock)', 0) or 0
    used_val = cm.get('Used', 0) or 0
    cond_model_rows += f"""
    <tr>
        <td>{cm['model']}</td>
        <td class="{'positive' if ds_val>0 else 'negative'}">{fmt_usd(ds_val)}</td>
        <td class="{'positive' if vnds_val>0 else 'negative'}">{fmt_usd(vnds_val)}</td>
        <td class="{'positive' if used_val>0 else 'negative'}">{fmt_usd(used_val)}</td>
    </tr>"""

# ── Below retail models ──
below_rows = ""
for b in d['below_model_data'][:8]:
    below_rows += f"""
    <tr>
        <td>{b['model']}</td>
        <td>{b['count']}</td>
        <td>{b['pct_of_model']}%</td>
        <td class="negative">{fmt_usd(b['avg_loss'])}</td>
    </tr>"""

# ── Yearly table ──
yearly_rows = ""
for y in d['yearly_data']:
    cls = 'positive' if y['avg_profit'] > 0 else 'negative'
    yearly_rows += f"""
    <tr>
        <td>{y['year']}</td>
        <td>{y['txns']}</td>
        <td>{fmt_usd(y['avg_resale'])}</td>
        <td class="{cls}">{fmt_usd(y['avg_profit'])}</td>
        <td>{y['premium_rate']}%</td>
        <td>{y['avg_days']}</td>
        <td>{fmt_usd(y['total_volume'])}</td>
    </tr>"""

# ── JSON-injectable data for charts ──
import json as _json

# Model profit chart
model_labels = _json.dumps([m['model'] for m in model_sorted])
model_profits = _json.dumps([m['avg_profit'] for m in model_sorted])
model_days = _json.dumps([m['avg_days'] for m in model_sorted])
model_premium = _json.dumps([m['premium_rate'] for m in model_sorted])

# Channel chart
chan_labels = _json.dumps([c['channel'] for c in d['channel_stats']])
chan_profits = _json.dumps([c['avg_profit'] for c in d['channel_stats']])
chan_days = _json.dumps([c['avg_days'] for c in d['channel_stats']])
chan_premium = _json.dumps([c['premium_rate'] for c in d['channel_stats']])

# Condition chart
cond_labels = _json.dumps([c['condition'] for c in d['condition_stats']])
cond_profits = _json.dumps([c['avg_profit'] for c in d['condition_stats']])
cond_premium = _json.dumps([c['premium_rate'] for c in d['condition_stats']])

# Monthly trends
m_labels = _json.dumps([m['month'] for m in d['monthly_data']])
m_profits = _json.dumps([m['avg_profit'] for m in d['monthly_data']])
m_days = _json.dumps([m['avg_days'] for m in d['monthly_data']])
m_premium = _json.dumps([m['premium_rate'] for m in d['monthly_data']])
m_txns = _json.dumps([m['txns'] for m in d['monthly_data']])

# Colorway chart
cw_labels = _json.dumps([c['colorway'] for c in d['colorway_stats'][:10]])
cw_profits = _json.dumps([c['avg_profit'] for c in d['colorway_stats'][:10]])
cw_premium = _json.dumps([c['premium_rate'] for c in d['colorway_stats'][:10]])

# Profit distribution
profit_labels = _json.dumps([p['bucket'] for p in d['profit_distribution']])
profit_counts = _json.dumps([p['count'] for p in d['profit_distribution']])

# Ratio distribution
ratio_labels = _json.dumps([r['bucket'] for r in d['ratio_distribution']])
ratio_counts = _json.dumps([r['count'] for r in d['ratio_distribution']])

# Monthly by condition
mc = d['monthly_cond']
mc_months = _json.dumps(mc['months'])
mc_ds = _json.dumps(mc.get('Deadstock (Brand New)', []))
mc_vnds = _json.dumps(mc.get('VNDS (Very Near Deadstock)', []))
mc_used = _json.dumps(mc.get('Used', []))

# Channel condition heatmap
cc_labels = _json.dumps([c['channel'] for c in d['channel_condition']])
cc_ds = _json.dumps([c.get('Deadstock (Brand New)', 0) or 0 for c in d['channel_condition']])
cc_vnds = _json.dumps([c.get('VNDS (Very Near Deadstock)', 0) or 0 for c in d['channel_condition']])
cc_used = _json.dumps([c.get('Used', 0) or 0 for c in d['channel_condition']])

# Quarterly
qtr_labels = _json.dumps([q['quarter'] for q in d['quarterly_data']])
qtr_profits = _json.dumps([q['avg_profit'] for q in d['quarterly_data']])
qtr_days = _json.dumps([q['avg_days'] for q in d['quarterly_data']])

# Yearly bar
yr_labels = _json.dumps([str(y['year']) for y in d['yearly_data']])
yr_profits = _json.dumps([y['avg_profit'] for y in d['yearly_data']])
yr_premium = _json.dumps([y['premium_rate'] for y in d['yearly_data']])

# Channel bubble data
